import{_ as o,o as r,c as n,a6 as t}from"./chunks/framework.QBF2cGGQ.js";const d=JSON.parse('{"title":"20 · 网络、系统与分布式基础","description":"","frontmatter":{},"headers":[],"relativePath":"guide/20-network-system.md","filePath":"guide/20-network-system.md","lastUpdated":1793330726000}'),i={name:"guide/20-network-system.md"};function a(p,s,l,e,g,c){return r(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="_20-·-网络、系统与分布式基础" tabindex="-1">20 · 网络、系统与分布式基础 <a class="header-anchor" href="#_20-·-网络、系统与分布式基础" aria-label="Permalink to &quot;20 · 网络、系统与分布式基础&quot;">​</a></h1><blockquote><p><strong>投入权重：5%</strong> · 补的一章。不需要背操作系统教材，但这些知识决定你<strong>能不能定位生产故障</strong>。</p><p>现实是：AI 应用 90% 的线上问题不在模型，在超时、连接、代理、流式缓冲、内存这些地方。</p></blockquote><h2 id="http-与连接" tabindex="-1">HTTP 与连接 <a class="header-anchor" href="#http-与连接" aria-label="Permalink to &quot;HTTP 与连接&quot;">​</a></h2><ul><li><strong>HTTP/1.1 与 HTTP/2 的差别</strong> <span class="prio prio-must">必须</span> — 队头阻塞、多路复用、头部压缩。<strong>流式场景下 HTTP/1.1 的 6 连接限制会卡住并发。</strong></li><li><strong>长连接与 Keep-Alive</strong> <span class="prio prio-must">必须</span> — 默认开启，但中间代理可能提前断。AI 长响应必须配心跳。</li><li><strong>SSE 的协议本质</strong> <span class="prio prio-must">必须</span> — 就是&quot;一个不结束的 HTTP 响应，按 <code>\\n\\n</code> 分段&quot;。它不是新协议，所以不需要特殊服务端支持，但<strong>极容易被代理缓冲</strong>。</li><li><strong><code>X-Accel-Buffering: no</code></strong> <span class="prio prio-must">必须</span> — Nginx 默认会缓冲响应，流式会变成&quot;等全部生成完才吐&quot;。这个头是必加的。</li><li><strong>超时的四个位置</strong> <span class="prio prio-must">必须</span> — 客户端、反向代理（proxy_read_timeout）、应用、上游 API。<strong>任何一层短了都会中断流式</strong>，排查时要逐层看。</li><li><strong>DNS 解析</strong> <span class="prio prio-imp">重要</span> — A/CNAME/TTL。内网服务用私有 DNS。<strong>解析失败和网络不通的表现很像，别误判。</strong></li><li><strong>TLS 握手与证书</strong> <span class="prio prio-imp">重要</span> — 证书链、SNI、自动续期（certbot）。证书过期是最低级的线上事故，但每年都有人犯。</li><li><strong>CORS 的真实机制</strong> <span class="prio prio-must">必须</span> — 预检请求、<code>Access-Control-Allow-Origin</code>、携带凭证时不能写 <code>*</code>。<strong>流式接口的 CORS 预检失败会表现成&quot;请求没发出去&quot;。</strong></li><li><strong>反向代理的作用</strong> <span class="prio prio-must">必须</span> — TLS 终止、负载均衡、静态资源、限流、缓冲。理解它在链路中的位置。</li><li><strong>gRPC 什么时候用</strong> <span class="prio prio-opt">选学</span> — 内部服务间高性能调用。AI 应用里少见，模型 API 基本都是 REST。</li></ul><h2 id="代理与网络出口-踩过的坑" tabindex="-1">代理与网络出口（踩过的坑） <a class="header-anchor" href="#代理与网络出口-踩过的坑" aria-label="Permalink to &quot;代理与网络出口（踩过的坑）&quot;">​</a></h2><ul><li><strong>HTTP_PROXY 大小写都要设</strong> <span class="prio prio-must">必须</span> — 很多库只读大写，很多只读小写。<strong>只设一个会出现&quot;某些请求走代理某些不走&quot;的诡异现象。</strong></li><li><strong><code>NO_PROXY</code> 的作用</strong> <span class="prio prio-must">必须</span> — 内网地址和 localhost 必须排除，否则内网请求被送去代理然后失败。</li><li><strong>代理与 SSE</strong> <span class="prio prio-must">必须</span> — 正向代理可能缓冲流式响应。要验证代理是否透传。</li><li><strong>内网域名解析到私网地址</strong> <span class="prio prio-imp">重要</span> — 如果域名解析出 10.x / 172.16-31.x / 192.168.x，说明只有内网可达，跟代理配置无关。<strong>先 <code>nslookup</code> 再怀疑网络。</strong></li><li><strong>出口 IP 白名单</strong> <span class="prio prio-imp">重要</span> — 企业网络常限制出站目标。表现为&quot;某些 API 通、某些超时&quot;，不是全断。</li></ul><h2 id="linux-基础" tabindex="-1">Linux 基础 <a class="header-anchor" href="#linux-基础" aria-label="Permalink to &quot;Linux 基础&quot;">​</a></h2><ul><li><strong>进程与端口</strong> <span class="prio prio-must">必须</span> — <code>ps</code> / <code>top</code> / <code>ss -tlnp</code> / <code>lsof -i</code>。<strong>&quot;端口被占用&quot;和&quot;服务没起来&quot;要能一眼分开。</strong></li><li><strong>文件描述符限制</strong> <span class="prio prio-imp">重要</span> — <code>ulimit -n</code>。高并发下 fd 耗尽的表现是&quot;连不上但 CPU 不高&quot;。</li><li><strong>内存与 OOM</strong> <span class="prio prio-must">必须</span> — <code>free -h</code> / <code>dmesg | grep -i oom</code>。Node 进程被 OOM killer 杀掉时没有堆栈，只能从这里看。</li><li><strong>磁盘与 inode</strong> <span class="prio prio-imp">重要</span> — <code>df -h</code> 和 <code>df -i</code>。日志写满磁盘是常见事故。</li><li><strong>日志位置</strong> <span class="prio prio-must">必须</span> — <code>/var/log/</code>、journalctl、容器日志。出问题第一件事是找日志。</li><li><strong>systemd 管理服务</strong> <span class="prio prio-imp">重要</span> — unit 文件、<code>Restart=always</code>、<code>Environment=</code>、日志到 journald。</li><li><strong>信号处理</strong> <span class="prio prio-must">必须</span> — SIGTERM（优雅关闭）、SIGKILL（无法捕获）、SIGHUP（重载配置）。</li><li><strong>网络诊断</strong> <span class="prio prio-must">必须</span> — <code>curl -v</code> 看握手、<code>traceroute</code> 看路径、<code>tcpdump</code> 抓包、<code>nc -zv</code> 测端口。</li><li><strong>时间与时区</strong> <span class="prio prio-imp">重要</span> — 服务器 UTC、数据库 timestamptz、前端本地化。<strong>混用会导致&quot;消息时间差 8 小时&quot;这种低级但难查的 bug。</strong></li></ul><h2 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to &quot;容器&quot;">​</a></h2><ul><li><strong>镜像分层与多阶段构建</strong> <span class="prio prio-must">必须</span> — 构建阶段装依赖，运行阶段只拷产物。能把镜像从 1G 降到 150M。</li><li><strong><code>.dockerignore</code></strong> <span class="prio prio-must">必须</span> — 不写会把 <code>node_modules</code> 和 <code>.git</code> 打进镜像，构建慢十倍。</li><li><strong>Volume 与数据持久化</strong> <span class="prio prio-must">必须</span> — 容器删了数据就没了，数据库必须挂卷。</li><li><strong>网络模式</strong> <span class="prio prio-imp">重要</span> — bridge 下容器间用服务名互访，<code>localhost</code> 指的是容器自己。</li><li><strong>健康检查</strong> <span class="prio prio-must">必须</span> — <code>HEALTHCHECK</code> 或 compose 的 healthcheck，编排系统靠它判断就绪。</li><li><strong>资源限制</strong> <span class="prio prio-imp">重要</span> — <code>--memory</code> / <code>--cpus</code>。不限制的话一个容器能把宿主机拖死。</li><li><strong>compose 编排本地栈</strong> <span class="prio prio-must">必须</span> — app + postgres + redis + nginx 一键起。<strong>这是你交付项目的标配。</strong></li></ul><h2 id="kubernetes-会用即可-不必会运维" tabindex="-1">Kubernetes（会用即可，不必会运维） <a class="header-anchor" href="#kubernetes-会用即可-不必会运维" aria-label="Permalink to &quot;Kubernetes（会用即可，不必会运维）&quot;">​</a></h2><p>面试写&quot;熟悉 K8s&quot;会被追问，写&quot;能写 Deployment、会看 Pod 日志&quot;更安全。<strong>目标是&quot;能上线、能排障&quot;，不是&quot;能搭集群&quot;。</strong></p><ul><li><strong>Pod / Deployment / Service 三件套</strong> <span class="prio prio-must">必须</span> — Pod 是最小单位，Deployment 管副本与滚动更新，Service 给 Pod 一个稳定入口。<strong>这三者的关系必须能画出来</strong>。</li><li><strong>Ingress</strong> <span class="prio prio-imp">重要</span> — 外部流量入口，本质是 Nginx/Traefik 的配置抽象。<strong>SSE 的 <code>proxy_buffering off</code> 要写在 Ingress 的 annotation 里</strong>，这是 AI 应用上 K8s 最容易漏的一条。</li><li><strong>ConfigMap / Secret</strong> <span class="prio prio-must">必须</span> — 配置与密钥分离。<strong>Secret 默认只是 base64，不是加密</strong>，要用 KMS 或 external-secrets。</li><li><strong>资源 requests / limits</strong> <span class="prio prio-must">必须</span> — requests 决定调度，limits 决定上限。<strong>limits 设得比 requests 高太多会导致节点过载</strong>。</li><li><strong>liveness / readiness / startup 探针</strong> <span class="prio prio-must">必须</span> — liveness 失败重启，readiness 失败摘流量，startup 用于慢启动。<strong>AI 服务启动要加载模型，必须配 startupProbe，否则会被反复重启</strong>。</li><li><strong>滚动更新与回滚</strong> <span class="prio prio-must">必须</span> — <code>maxSurge</code> / <code>maxUnavailable</code>，<code>kubectl rollout undo</code>。<strong>没有回滚方案就不要上线</strong>。</li><li><strong>HPA 自动扩缩</strong> <span class="prio prio-imp">重要</span> — 按 CPU/内存/QPS 扩。<strong>LLM 服务扩 Pod 没用</strong>（瓶颈在模型侧），要扩的是 worker。</li><li><strong>持久卷 PVC</strong> <span class="prio prio-imp">重要</span> — 有状态服务要挂卷。<strong>AI 应用尽量无状态，状态放 PG/对象存储</strong>。</li><li><strong>看日志与进容器</strong> <span class="prio prio-must">必须</span> — <code>kubectl logs -f</code>、<code>kubectl exec -it</code>、<code>kubectl describe pod</code>（看 Events）。<strong><code>describe</code> 是排障第一命令</strong>，镜像拉取失败、探针失败、OOMKilled 都在这里。</li><li><strong>GPU 调度</strong> <span class="prio prio-opt">选学</span> — 自部署模型才需要。device plugin、节点亲和、GPU 共享。</li><li><strong>不要自己搭集群</strong> <span class="prio prio-must">必须</span> — 用云托管（ACK/TKE/EKS）或 Serverless 容器。<strong>自建 K8s 是专职岗位，不是应用工程师的活</strong>。</li></ul><h2 id="devops-与交付流水线" tabindex="-1">DevOps 与交付流水线 <a class="header-anchor" href="#devops-与交付流水线" aria-label="Permalink to &quot;DevOps 与交付流水线&quot;">​</a></h2><ul><li><strong>CI/CD 的最小闭环</strong> <span class="prio prio-must">必须</span> — push → lint → 单测 → 构建镜像 → 推送仓库 → 部署到 staging → 冒烟测试 → 手动批准 → 生产。<strong>能画出这条链就够</strong>。</li><li><strong>流水线要跑什么</strong> <span class="prio prio-must">必须</span> — 类型检查、lint、单测、构建。<strong>AI 应用额外加一条：prompt 回归测试</strong>（见 <a href="/ai-eng-roadmap/guide/07-evals">07 · 评测</a>）。</li><li><strong>构建缓存</strong> <span class="prio prio-imp">重要</span> — 依赖层单独一层，代码层后置。<strong>没有缓存时一次构建 8 分钟，有缓存 40 秒</strong>，差别决定你一天能提交几次。</li><li><strong>环境一致性</strong> <span class="prio prio-must">必须</span> — 同一个镜像跑遍 dev/staging/prod，差异只在配置。<strong>&quot;测试环境好的，生产不行&quot;九成是环境不一致</strong>。</li><li><strong>数据库迁移</strong> <span class="prio prio-must">必须</span> — 迁移脚本进仓库、随版本执行、<strong>必须可回滚或向前兼容</strong>。禁止手工改生产库。</li><li><strong>灰度与特性开关</strong> <span class="prio prio-must">必须</span> — 新 prompt / 新模型按用户比例放量。<strong>开关是&quot;秒级止损&quot;的唯一手段</strong>。</li><li><strong>制品与版本号</strong> <span class="prio prio-must">必须</span> — 镜像 tag 用 git commit sha，<strong>永远不要用 <code>latest</code></strong>。出问题要能定位到确切代码。</li><li><strong>密钥注入</strong> <span class="prio prio-must">必须</span> — 走 CI 的 secret 管理或 KMS，<strong>不要写进 Dockerfile、不要进镜像层</strong>。</li><li><strong>监控告警</strong> <span class="prio prio-must">必须</span> — 见 <a href="/ai-eng-roadmap/guide/08-observability">08 · 可观测</a>。<strong>告警要能叫醒人，也要能不叫醒人</strong>——只报&quot;需要人做决定&quot;的事。</li><li><strong>日常运维清单</strong> <span class="prio prio-imp">重要</span> — 磁盘、证书到期、备份是否成功、队列积压、慢查询 Top10。<strong>做成每日巡检脚本，别靠记忆</strong>。</li><li><strong>审计日志</strong> <span class="prio prio-imp">重要</span> — 谁在什么时候部署了什么、改了哪个配置。<strong>合规要求，也是事故复盘的依据</strong>。</li></ul><h2 id="分布式基础-够用就行" tabindex="-1">分布式基础（够用就行） <a class="header-anchor" href="#分布式基础-够用就行" aria-label="Permalink to &quot;分布式基础（够用就行）&quot;">​</a></h2><ul><li><strong>幂等</strong> <span class="prio prio-must">必须</span> — 同一个请求执行多次结果相同。实现：幂等键 + 唯一约束 / 状态机判断。<strong>AI 场景的重试、超时重发都依赖它。</strong></li><li><strong>至少一次投递</strong> <span class="prio prio-must">必须</span> — 消息队列默认语义。所以消费端必须幂等，不能假设&quot;只来一次&quot;。</li><li><strong>重试与指数退避</strong> <span class="prio prio-must">必须</span> — 1s、2s、4s、8s，加抖动（jitter）避免同时重试打爆。</li><li><strong>熔断</strong> <span class="prio prio-must">必须</span> — 连续失败 N 次后直接拒绝，过一段时间半开试探。<strong>上游模型挂了时，不熔断会拖垮整个服务。</strong></li><li><strong>限流</strong> <span class="prio prio-must">必须</span> — 令牌桶/漏桶/滑动窗口。按用户、按租户、按接口分别限。</li><li><strong>降级</strong> <span class="prio prio-must">必须</span> — 主模型超时切备用、AI 不可用退回搜索/模板。<strong>降级方案要在设计时就定，不是出事时想。</strong></li><li><strong>最终一致性</strong> <span class="prio prio-imp">重要</span> — 索引更新、成本统计这类可以异步，但要能对账。</li><li><strong>分布式锁</strong> <span class="prio prio-imp">重要</span> — 防重复索引、防重复执行同一任务。Redis 实现要校验持有者。</li><li><strong>CAP 的实际含义</strong> <span class="prio prio-opt">选学</span> — 网络分区时在一致性和可用性之间选。多数业务选可用性 + 最终一致。</li></ul><h2 id="微服务基础设施-知道每个解决什么问题就够" tabindex="-1">微服务基础设施（知道每个解决什么问题就够） <a class="header-anchor" href="#微服务基础设施-知道每个解决什么问题就够" aria-label="Permalink to &quot;微服务基础设施（知道每个解决什么问题就够）&quot;">​</a></h2><p><strong>你是前端转岗，不需要搭微服务，但面试官会用这些词问&quot;你们系统怎么组织的&quot;。</strong> 每个组件只要答出&quot;它解决什么问题、没有它会怎样&quot;就够，不必会部署。</p><ul><li><strong>API Gateway</strong> <span class="prio prio-must">必须</span> — 统一入口：鉴权、限流、路由、协议转换、日志。<strong>没有它，每个服务都要自己实现一遍鉴权</strong>。AI 应用里网关还要多做一件事：<strong>token 计量与成本归因</strong>（见 <a href="/ai-eng-roadmap/guide/10-architecture">10 · 架构</a>）。</li><li><strong>Service Discovery（服务发现）</strong> <span class="prio prio-must">必须</span> — 服务实例动态增减，调用方怎么找到它。两种模式：<strong>客户端发现</strong>（Consul/etcd，调用方自己选）和<strong>服务端发现</strong>（K8s Service / 负载均衡器代劳）。<strong>K8s 环境下你基本不用自己操心</strong>。</li><li><strong>Configuration Center（配置中心）</strong> <span class="prio prio-must">必须</span> — 配置集中管理 + 热更新 + 版本回滚。<strong>AI 应用里它管的是 prompt 版本、模型名、阈值</strong>——这类配置改得比代码频繁得多，<strong>必须能不发版就改、改错能秒回滚</strong>。</li><li><strong>Load Balancing（负载均衡）</strong> <span class="prio prio-imp">重要</span> — 四层（TCP，看 IP/端口）vs 七层（HTTP，看路径/Header）。<strong>算法</strong>：轮询、加权、最少连接、一致性哈希（同一用户打到同一实例，利于缓存）。<strong>注意：LLM 服务扩 Pod 收益低，瓶颈在模型侧</strong>。</li><li><strong>Service Mesh（服务网格）</strong> <span class="prio prio-opt">选学</span> — 把流量治理（重试、熔断、mTLS、链路追踪）从业务代码里抽到 Sidecar。<strong>理念好，但运维成本高</strong>。<strong>小团队别上</strong>，用 SDK 或网关解决就行。</li><li><strong>分布式事务</strong> <span class="prio prio-must">必须</span> — 跨服务/跨库的原子性。<strong>能不用就不用</strong>——先想能不能改成单库、能不能改成异步最终一致。真要用的方案见下。</li><li><strong>2PC（两阶段提交）</strong> <span class="prio prio-opt">选学</span> — 强一致但阻塞、性能差、协调者单点。<strong>互联网业务基本不用</strong>。</li><li><strong>Saga Pattern</strong> <span class="prio prio-must">必须</span> — 长事务拆成多个本地事务，每步配一个补偿动作（undo）。<strong>失败就反向执行补偿</strong>。这是<strong>互联网主流方案</strong>，和 <a href="/ai-eng-roadmap/guide/04-agent">04 · Agent</a> 的补偿链、<a href="/ai-eng-roadmap/guide/22-memory">22 · 记忆</a> 的 Saga 是同一套思路。</li><li><strong>TCC（Try-Confirm-Cancel）</strong> <span class="prio prio-imp">重要</span> — 业务层三段式预留/确认/取消。比 Saga 强一致，但<strong>每个业务都要写三个接口</strong>，成本高。适合资金类。</li><li><strong>本地消息表 / Outbox</strong> <span class="prio prio-must">必须</span> — 最实用的方案：业务表和消息表同事务写入，另一个进程轮询发消息。<strong>&quot;最终一致&quot;的性价比之王</strong>，见 <a href="/ai-eng-roadmap/guide/19-database">19 · 数据库</a>。</li><li><strong>幂等是分布式事务的前提</strong> <span class="prio prio-must">必须</span> — 任何补偿、重试、重放都要求幂等。<strong>没有幂等，Saga 会把数据搞得更乱</strong>。</li></ul><h2 id="容量与伸缩" tabindex="-1">容量与伸缩 <a class="header-anchor" href="#容量与伸缩" aria-label="Permalink to &quot;容量与伸缩&quot;">​</a></h2><ul><li><strong>无状态服务设计</strong> <span class="prio prio-must">必须</span> — 服务不把状态存在本地内存/本地磁盘，<strong>状态放 Redis / DB / 对象存储</strong>。这是&quot;能水平扩容&quot;的前提。<strong>AI 应用的会话状态、上传的临时文件都要外置</strong>。</li><li><strong>水平扩容（Scale Out）</strong> <span class="prio prio-must">必须</span> — 加机器。前提是无状态 + 有负载均衡。<strong>垂直扩容（加 CPU 内存）有上限，水平没有</strong>。</li><li><strong>有状态服务的扩容</strong> <span class="prio prio-imp">重要</span> — 数据库、队列、向量库扩容要分片/迁移。<strong>这类是扩容的难点，设计时要尽量少</strong>。</li><li><strong>容量估算</strong> <span class="prio prio-must">必须</span> — QPS × 平均耗时 = 并发数（利特尔法则）。<strong>再加 30~50% 余量</strong>。<strong>AI 应用别忘算 token 成本和下游限流</strong>。</li><li><strong>压测要压到崩</strong> <span class="prio prio-must">必须</span> — k6 / JMeter / autocannon。<strong>只压到&quot;看起来正常&quot;没有意义，必须找到拐点</strong>。</li><li><strong>扩容的滞后性</strong> <span class="prio prio-imp">重要</span> — 自动扩容要几十秒到几分钟。<strong>突发流量靠扩容来不及，要靠限流 + 排队兜住</strong>。</li><li><strong>缩容比扩容难</strong> <span class="prio prio-opt">选学</span> — 缩太快会打断在途请求。要优雅停机（先摘流量、等在途完成、再退出）。</li><li><strong>容灾与高可用</strong> <span class="prio prio-must">必须</span> — 多可用区部署、故障转移、RPO/RTO。见 <a href="/ai-eng-roadmap/guide/10-architecture">10 · 架构</a> 的 Backup/DR。</li><li><strong>单点识别</strong> <span class="prio prio-must">必须</span> — 画一遍架构图，<strong>每个&quot;只有一个&quot;的东西都是单点</strong>：单库、单 Redis、单网关、单模型供应商。<strong>逐个问&quot;它挂了怎么办&quot;</strong>。</li></ul><h2 id="排障方法论-这一节最实用" tabindex="-1">排障方法论（这一节最实用） <a class="header-anchor" href="#排障方法论-这一节最实用" aria-label="Permalink to &quot;排障方法论（这一节最实用）&quot;">​</a></h2><p>线上出问题，按这个顺序查，能覆盖 90% 的情况：</p><ol><li><strong>是全挂还是部分挂</strong> —— 全挂看 DNS/证书/网络出口；部分挂看特定用户/特定模型/特定区域</li><li><strong>是慢还是错</strong> —— 慢看连接池、上游延迟、N+1 查询；错看日志里的错误分类</li><li><strong>什么时候开始的</strong> —— 对齐发布记录、配置变更、上游状态页</li><li><strong>能不能复现</strong> —— 用 trace 里的 requestId 重放</li><li><strong>影响面多大</strong> —— 看错误率曲线和影响用户数，决定是回滚还是热修</li></ol><p><strong>AI 应用特有的坑</strong>：接口 200、响应正常、内容全错。这种情况所有传统监控都抓不到，只能靠 trace + 评测。这就是为什么第 08 章（可观测）和第 07 章（评测）权重给得高。</p><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><p>能独立回答这几个问题就算过关：</p><ul><li>流式响应在 Nginx 后面变成一次性返回，怎么查？</li><li>服务 CPU 不高但连不上，可能是什么原因？</li><li>模型 API 偶尔超时，怎么设计才能不影响用户体验？</li><li>发布时怎么做到零请求丢失？</li></ul>',29)])])}const m=o(i,[["render",a]]);export{d as __pageData,m as default};
